"""Actual native Chrome checks; isolated admitted copies, CPU only, no model requests."""
import asyncio,json,os,shutil,subprocess,tempfile,urllib.request,hashlib
from pathlib import Path
from playwright.async_api import async_playwright,expect
ROOT=Path(__file__).resolve().parents[1];URL='http://127.0.0.1:5141'
async def main():
 checks=[];original=ROOT/'fixtures/source-v1.json';before=hashlib.sha256(original.read_bytes()).hexdigest();out=ROOT/'docs';out.mkdir(exist_ok=True)
