    await page.locator('#lines button').first.focus();await page.keyboard.press('Enter');await expect(page.locator('#source-evidence')).to_contain_text('SRC-A-L1');assert await page.evaluate("document.activeElement.id")=='source-evidence';checked('Keyboard Enter opens named source destination')
