    await page.locator('#order').select_option('SO-C');await expect(page.locator('#heading')).to_contain_text('SO-C');await expect(page.locator('#event-summary')).to_have_text('3 unique source events · 1 transport duplicates · 2 instances · 1 active blocks');await expect(page.locator('#queue')).to_contain_text('BLK-C2');await expect(page.locator('#questions')).to_contain_text('Responsible role is unknown');await expect(page.locator('#history')).to_contain_text('fictional seeded');checked('Exact duplicate transport, current instance and seeded historical receipt')
    await page.locator('#revision').select_option('3');await expect(page.locator('#authority')).to_have_text('HISTORICAL SOURCE VIEW');await expect(page.locator('#review')).to_be_disabled();checked('Historical revision cannot authorize current review')
    await page.locator('#revision').select_option('4');await expect(page.locator('#authority')).to_have_text('CURRENT SOURCE VIEW');await page.locator('#confirm').check();await page.locator('#review').click();await expect(page.locator('#status')).to_contain_text('LOCAL REVIEW RECORDED');await expect(page.locator('#history')).to_contain_text('CURRENT LOCAL RECEIPT');await page.locator('#confirm').check();await page.locator('#review').click();await expect(page.locator('#status')).to_contain_text('existing receipt');assert await page.locator('#history p').count()==2;checked('Repeated acknowledgment is idempotent; block remains active');await expect(page.locator('#queue')).to_contain_text('BLK-C2');await page.screenshot(path=str(out/'event-handoff-review.png'),full_page=True)
    await page.locator('#confirm').check()
