    download=await download_info.value;await download.save_as(str(ROOT/'evidence/executed-local-receipt.json'));await expect(page.locator('#status')).to_contain_text('download completion');checked('Exact local receipt export scope; no target import/release claim')
    await page.locator('#role').select_option('Authorized Commercial Review');await expect(page.locator('#status')).to_contain_text('CURRENT');await page.locator('#order').select_option('SO-B');await expect(page.locator('#notes')).to_contain_text('Fictional commercial-only');await page.locator('#notes button').click();await expect(page.locator('#source-evidence')).to_contain_text('SYNTHETIC-B-CANARY');checked('Explicit fictional commercial projection can inspect its own source')
    issued=asyncio.Event();gate=asyncio.Event();delivered=asyncio.Event();captured=[]
