    await page.set_viewport_size({'width':390,'height':844});await page.screenshot(path=str(out/'mobile-390.png'),full_page=True);assert await page.evaluate('document.documentElement.scrollWidth<=innerWidth');sizes=await page.locator('table,button,label,pre,.subtle').evaluate_all("es=>es.filter(e=>e.getClientRects().length).map(e=>parseFloat(getComputedStyle(e).fontSize))");assert min(sizes)>=14;checked('390px readable native text and scrollable exact-key table',{'min_font_px':min(sizes),'no_page_overflow':True})
    await page.set_viewport_size({'width':1440,'height':1050});await page.locator('#order').select_option('SO-C');await expect(page.locator('#heading')).to_contain_text('SO-C');await page.locator('#confirm').check();source.rename(source.with_suffix('.held'));await page.locator('#refresh').click();await expect(page.locator('#status')).to_contain_text('authority revoked');await expect(page.locator('#review')).to_be_disabled();await expect(page.locator('#receipt')).to_be_disabled();assert not await page.locator('#confirm').is_checked();checked('Missing isolated source revokes current authority and actions');await page.screenshot(path=str(out/'source-unavailable.png'),full_page=True);source.with_suffix('.held').rename(source)
    await page.reload();await expect(page.locator('#status')).to_contain_text('CURRENT');policy.rename(policy.with_suffix('.held'));await page.locator('#refresh').click();await expect(page.locator('#status')).to_contain_text('authority revoked');checked('Missing isolated policy revokes all current evidence');policy.with_suffix('.held').rename(policy)
    await page.reload();await expect(page.locator('#status')).to_contain_text('CURRENT');await page.locator('#role').focus();await page.keyboard.press('Tab');assert await page.evaluate('document.activeElement.id')=='order';checked('Actual Tab sequence keeps named native controls');assert not errors;checked('No browser JavaScript errors');recording.cancel()
